      "end": "p2:L10"
    },
    {
      "item_code": "S4_SKIN",
      "title_raw": "나. 피부에 접촉했을 때",
      "start": "p2:L11",
      "end": "p2:L12"
    },
    {
      "item_code": "S4_INHAL",
